// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// AdminListOrganizations Every organization with its owner, oldest first (Platform Admin)
	// (GET /admin/organizations)
	AdminListOrganizations(ctx context.Context, request AdminListOrganizationsRequestObject) (AdminListOrganizationsResponseObject, error)
	// ApproveOrganization Approve an organization request with its entitlement and default cluster grant (Platform Admin)
	// (POST /admin/organizations/{orgId}:approve)
	ApproveOrganization(ctx context.Context, request ApproveOrganizationRequestObject) (ApproveOrganizationResponseObject, error)
	// RejectOrganization Reject an organization request with a reason the requester sees (Platform Admin)
	// (POST /admin/organizations/{orgId}:reject)
	RejectOrganization(ctx context.Context, request RejectOrganizationRequestObject) (RejectOrganizationResponseObject, error)
	// DeleteGroup Delete a group (OrgOwner or OrgAdmin of its organization)
	// (DELETE /groups/{groupId})
	DeleteGroup(ctx context.Context, request DeleteGroupRequestObject) (DeleteGroupResponseObject, error)
	// PatchGroup Rename a group (OrgOwner or OrgAdmin of its organization)
	// (PATCH /groups/{groupId})
	PatchGroup(ctx context.Context, request PatchGroupRequestObject) (PatchGroupResponseObject, error)
	// RemoveGroupMember Take someone out of the group (OrgOwner or OrgAdmin)
	// (DELETE /groups/{groupId}/members/{userId})
	RemoveGroupMember(ctx context.Context, request RemoveGroupMemberRequestObject) (RemoveGroupMemberResponseObject, error)
	// AddGroupMember Add a member of the organization to the group (OrgOwner or OrgAdmin)
	// (PUT /groups/{groupId}/members/{userId})
	AddGroupMember(ctx context.Context, request AddGroupMemberRequestObject) (AddGroupMemberResponseObject, error)
	// RevokeInvitation Revoke an open invitation (OrgOwner or OrgAdmin of its organization)
	// (DELETE /invitations/{invitation})
	RevokeInvitation(ctx context.Context, request RevokeInvitationRequestObject) (RevokeInvitationResponseObject, error)
	// PreviewInvitation What an invitation link offers, before accepting it (any logged-in person)
	// (GET /invitations/{invitation})
	PreviewInvitation(ctx context.Context, request PreviewInvitationRequestObject) (PreviewInvitationResponseObject, error)
	// AcceptInvitation Join the organization of an invitation
	// (POST /invitations/{token}:accept)
	AcceptInvitation(ctx context.Context, request AcceptInvitationRequestObject) (AcceptInvitationResponseObject, error)
	// GetMe The signed-in user
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// GetOperation Progress of an asynchronous change (any member of its organization, or a Platform Admin)
	// (GET /operations/{operationId})
	GetOperation(ctx context.Context, request GetOperationRequestObject) (GetOperationResponseObject, error)
	// RetryOperation Retry a Failed operation (OrgOwner, OrgAdmin or Platform Admin)
	// (POST /operations/{operationId}:retry)
	RetryOperation(ctx context.Context, request RetryOperationRequestObject) (RetryOperationResponseObject, error)
	// ListOrganizations Organizations the caller belongs to, including their own Pending and Rejected requests
	// (GET /organizations)
	ListOrganizations(ctx context.Context, request ListOrganizationsRequestObject) (ListOrganizationsResponseObject, error)
	// CreateOrganization Request a new organization (PRODUCT-PLAN §4.2)
	// (POST /organizations)
	CreateOrganization(ctx context.Context, request CreateOrganizationRequestObject) (CreateOrganizationResponseObject, error)
	// GetOrganization Organization detail (any member)
	// (GET /organizations/{orgId})
	GetOrganization(ctx context.Context, request GetOrganizationRequestObject) (GetOrganizationResponseObject, error)
	// PatchOrganization Update display name or description (OrgOwner or OrgAdmin). Slug is immutable.
	// (PATCH /organizations/{orgId})
	PatchOrganization(ctx context.Context, request PatchOrganizationRequestObject) (PatchOrganizationResponseObject, error)
	// GetEntitlement What the organization was granted (OrgOwner or OrgAdmin)
	// (GET /organizations/{orgId}/entitlement)
	GetEntitlement(ctx context.Context, request GetEntitlementRequestObject) (GetEntitlementResponseObject, error)
	// ListGroups Groups of the organization with their members, by name (OrgOwner or OrgAdmin)
	// (GET /organizations/{orgId}/groups)
	ListGroups(ctx context.Context, request ListGroupsRequestObject) (ListGroupsResponseObject, error)
	// CreateGroup Create a group (OrgOwner or OrgAdmin)
	// (POST /organizations/{orgId}/groups)
	CreateGroup(ctx context.Context, request CreateGroupRequestObject) (CreateGroupResponseObject, error)
	// ListInvitations Open invitations of the organization, newest first (OrgOwner or OrgAdmin)
	// (GET /organizations/{orgId}/invitations)
	ListInvitations(ctx context.Context, request ListInvitationsRequestObject) (ListInvitationsResponseObject, error)
	// CreateInvitation Invite someone by email (OrgOwner or OrgAdmin)
	// (POST /organizations/{orgId}/invitations)
	CreateInvitation(ctx context.Context, request CreateInvitationRequestObject) (CreateInvitationResponseObject, error)
	// ListMembers Members of the organization with their groups (OrgOwner or OrgAdmin)
	// (GET /organizations/{orgId}/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// LeaveOrganization Leave the organization (any member but the owner)
	// (POST /organizations/{orgId}/members/me:leave)
	LeaveOrganization(ctx context.Context, request LeaveOrganizationRequestObject) (LeaveOrganizationResponseObject, error)
	// RemoveMember Remove a member from the organization (OrgOwner or OrgAdmin)
	// (DELETE /organizations/{orgId}/members/{userId})
	RemoveMember(ctx context.Context, request RemoveMemberRequestObject) (RemoveMemberResponseObject, error)
	// PatchMember Make a member an OrgAdmin or an OrgMember (OrgOwner or OrgAdmin)
	// (PATCH /organizations/{orgId}/members/{userId})
	PatchMember(ctx context.Context, request PatchMemberRequestObject) (PatchMemberResponseObject, error)
	// GetOwnershipTransfer The ownership transfer waiting in the organization (its owner and its recipient)
	// (GET /organizations/{orgId}/ownership-transfer)
	GetOwnershipTransfer(ctx context.Context, request GetOwnershipTransferRequestObject) (GetOwnershipTransferResponseObject, error)
	// GetUsage What the organization uses, next to its limits (OrgOwner or OrgAdmin)
	// (GET /organizations/{orgId}/usage)
	GetUsage(ctx context.Context, request GetUsageRequestObject) (GetUsageResponseObject, error)
	// TransferOwnership Offer the organization to one of its OrgAdmins (OrgOwner only)
	// (POST /organizations/{orgId}:transfer-ownership)
	TransferOwnership(ctx context.Context, request TransferOwnershipRequestObject) (TransferOwnershipResponseObject, error)
	// CancelOwnershipTransfer Withdraw (the owner) or decline (the recipient) a waiting transfer
	// (DELETE /ownership-transfers/{transferId})
	CancelOwnershipTransfer(ctx context.Context, request CancelOwnershipTransferRequestObject) (CancelOwnershipTransferResponseObject, error)
	// AcceptOwnershipTransfer Become the owner (the recipient only)
	// (POST /ownership-transfers/{transferId}:accept)
	AcceptOwnershipTransfer(ctx context.Context, request AcceptOwnershipTransferRequestObject) (AcceptOwnershipTransferResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

